def exact_keys(record, names):
    obj = expect_dict(record)
    if len(obj) != len(names):
        raise Invalid()
    for name in names:
        if name not in obj:
            raise Invalid()
    return obj


def asn(value):
    if type(value) is not int or value < 1 or value > MAX_ASN:
        raise Invalid()
    return value


def weight(value, low):
    if type(value) is not int or value < low or value > MAX_WEIGHT:
        raise Invalid()
    return value


def raw_path(obj):
    items = expect_list(obj)
    if len(items) > MAX_RAW_PATH:
        raise Invalid()
    return [asn(v) for v in items]


def link_pair(obj):
    items = expect_list(obj)
    if len(items) != 2:
        raise Invalid()
    u = asn(items[0])
    v = asn(items[1])
    if u == v:
        raise Invalid()
    return (u, v)


def canonical(u, v):
    return (u, v) if u < v else (v, u)


def key_dir(u, v):
    """Canonical link plus True when the observed direction is canonical."""
    if u < v:
        return (u, v), True
    return (v, u), False


def normalize(raw, ixps):
    """Drop IXPs first, then collapse each maximal run of duplicates."""
    out = []
    for value in raw:
        if value in ixps:
            continue
        if out and out[-1] == value:
            continue
        out.append(value)
    return tuple(out), len(set(out)) != len(out)


